const imageResults = $input.first().json.imageResults;
const data = JSON.parse(imageResults[0].dataStr);

imageResults.forEach(result => {
  if (result.ogImage) {
    data.top3[result.scrapeIndex].imagen = result.ogImage;
  }
});

data.actualizadoAt = new Date().toISOString();

const payload = JSON.stringify(data);
const upstashBody = JSON.stringify(['SET', 'noticias:tech', payload, 'EX', '90000']);

// Preparar body para BD Postgres (snapshot histórico)
const snapshotBody = JSON.stringify({ kind: 'noticias-tech', payload: data });

return [{ json: { upstashBody, snapshotBody, fecha: data.fecha } }];

const originalItems = $('Preparar scraping').all();
const scrapedItems = $input.all();

return scrapedItems.map((item, i) => {
  const original = originalItems[i].json;
  let ogImage = '';

  try {
    const html = (item.json.data || item.json.body || '') + '';

    const match =
      html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i) ||
      html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["']/i) ||
      html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["']/i) ||
      html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']twitter:image["']/i);

    if (match && match[1]) {
      ogImage = match[1].trim()
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'");
    }
  } catch (e) {
    // scraping falló para este item — imagen queda vacía
  }

  return {
    json: {
      scrapeIndex: original.scrapeIndex,
      ogImage,
      dataStr: original.dataStr,
    }
  };
});

// Separar las 5 URLs del top3 en items individuales para scrapear en paralelo
const data = $input.first().json.data;
const dataStr = JSON.stringify(data);

return data.top3.map((noticia, index) => ({
  json: {
    scrapeIndex: index,
    scrapeUrl: noticia.url,
    dataStr,
  }
}));

// Parsear respuesta de Claude — robusto a bloques thinking/text y a cambios de modelo
const raw = $input.first().json.content;
let text = '';

if (typeof raw === 'string') {
  text = raw;
} else if (Array.isArray(raw)) {
  const textBlock = raw.filter(b => b && b.type === 'text').pop();
  text = textBlock ? textBlock.text : raw.map(b => (b && b.text) || '').join('');
}

if (!text) {
  throw new Error('Respuesta de Claude sin bloque de texto. Raw: ' + JSON.stringify($input.first().json).slice(0, 300));
}

text = text.replace(/```json|```/g, '');
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (!jsonMatch) throw new Error('Claude no devolvió JSON válido. Raw: ' + text.slice(0, 200));

const data = JSON.parse(jsonMatch[0]);

// Fecha en TZ Argentina
data.fecha = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' });

// Validaciones estructurales (sí cortan: si esto falla, el brief está roto y conviene reintentar)
if (!Array.isArray(data.top3) || data.top3.length !== 5) throw new Error('top3 inválido: ' + JSON.stringify(data.top3));
if (!Array.isArray(data.tendencias) || data.tendencias.length !== 3) throw new Error('tendencias inválido');
if (!data.resumen || !data.conclusion) throw new Error('Falta resumen o conclusion');

const CATEGORIAS = ['framework', 'ai', 'security', 'infra', 'devops', 'industry', 'opensource', 'hardware'];
const normalizar = s => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

// --- Índice de URLs del input (para validar sin falsos positivos) ---
const articlesText = $('Formatear artículos').first().json.articles || '';
const hostOf = (u) => { try { return new URL(String(u).trim()).hostname.replace(/^www\./, '').toLowerCase(); } catch { return ''; } };
const slugOf = (u) => { try { return new URL(String(u).trim()).pathname.replace(/\/+$/, '').split('/').pop().toLowerCase(); } catch { return ''; } };
const normUrl = (u) => { try { const x = new URL(String(u).trim()); return (x.hostname.replace(/^www\./, '') + x.pathname).replace(/\/+$/, '').toLowerCase(); } catch { return String(u || '').trim().toLowerCase(); } };

const inputUrls = articlesText.match(/https?:\/\/\S+/g) || [];
const inputNormSet = new Set(inputUrls.map(normUrl));
const inputByDomain = {};
for (const u of inputUrls) {
  const d = hostOf(u); if (!d) continue;
  (inputByDomain[d] = inputByDomain[d] || []).push({ slug: slugOf(u), raw: u.replace(/[)\].,]+$/, '') });
}

const urlsDudosas = [];

for (const item of data.top3) {
  // categoría: normaliza y, si es inválida, cae a 'industry' en vez de cortar
  item.categoria = normalizar(item.categoria);
  if (!CATEGORIAS.includes(item.categoria)) item.categoria = 'industry';

  // URL: NUNCA corta la corrida
  if (typeof item.url !== 'string' || !/^https?:\/\//.test(item.url)) {
    item.url = '';
    item.urlVerificada = false;
    urlsDudosas.push('(url inválida o vacía)');
  } else if (inputNormSet.has(normUrl(item.url))) {
    item.urlVerificada = true;                          // match exacto con el input
  } else {
    const dom = hostOf(item.url);
    const cands = inputByDomain[dom] || [];
    const s = slugOf(item.url);
    const m = cands.find(c => c.slug && (c.slug === s || (s && (c.slug.includes(s) || s.includes(c.slug)))));
    if (m) {
      item.url = m.raw;                                 // mismo artículo, path distinto -> reescribo al del input
      item.urlVerificada = true;
    } else {
      item.urlVerificada = false;                       // no verificable: la dejo pasar igual
      urlsDudosas.push(item.url);
    }
  }

  // La imagen la llena el flujo con og:image, nunca el modelo
  item.imagen = '';
}

// alertas_seguridad: string o null (tolerar array por las dudas)
if (Array.isArray(data.alertas_seguridad)) data.alertas_seguridad = data.alertas_seguridad.join(' · ');
if (data.alertas_seguridad === '' || data.alertas_seguridad === 'null') data.alertas_seguridad = null;

// Debug temporal: qué dominios llegaron al input y qué URLs no se pudieron verificar.
// Sacá este bloque una vez confirmado que todo entra bien.
data._debug = { dominiosInput: Object.keys(inputByDomain).sort(), urlsDudosas };

return [{ json: { data } }];
